; Low-fuel alarm
; $4900-$4965

; Plays the fuel alarm on voice 2 when jet_state bit 6 (low fuel) or bit 7 (no fuel) is set. It sweeps the pitch up and flashes the GAS gauge red and white. When the fuel is good, it resets voice 2 once ($49f0).
fuel_alarm
        lda jet_state
        and #$c0
        beq fuel_alarm_none
; not executed $4906-$494c
        lda #$00                        ; $27 = 0: voice 2 is no longer in its reset state.
        sta voice2_idle
        lda alarm_pitch                 ; $29 = alarm pitch. Bit 7 set = the silent part of the cycle.
        bmi fuel_alarm_off_phase
        lda alarm_phase                 ; $28 = 0 loads the alarm sound into voice 2.
        bne fuel_alarm_rise
        jsr fuel_alarm_sound_start
fuel_alarm_rise
        lda alarm_pitch
        clc
        adc #$02
        sta alarm_pitch
        sta FREHI2
        cmp #$58                        ; The pitch rises by 2 up to $58.
        bcc fuel_alarm_flash_gauge
        lda #$00
        sta alarm_phase
        lda #$fd
        sta alarm_pitch
        bne fuel_alarm_flash_gauge
fuel_alarm_off_phase
        lda alarm_phase
        bne fuel_alarm_off_step
        inc alarm_phase
        lda #$20                        ; Voice 2: sawtooth, gate off.
        sta VCREG2
        lda #$10
        sta FREHI2
fuel_alarm_off_step
        inc alarm_pitch
        lda alarm_pitch
        bmi fuel_alarm_flash_gauge
        lda #$00
        sta alarm_phase
        lda #$10
        sta alarm_pitch
        bne fuel_alarm_flash_gauge
fuel_alarm_none
        lda voice2_idle                 ; $27 = 0: voice 2 is not reset yet.
        bne fuel_alarm_ok_done
        jsr voice2_reset
fuel_alarm_ok_done
        clc                             ; Always branches.
        bcc fuel_alarm_done
; Sets the GAS gauge colour $2e from bit 2 of $29: 2 (red) or 1 (white).
fuel_alarm_flash_gauge
; not executed $4957-$4964
        lda alarm_pitch
        and #$04
        bne fuel_alarm_gauge_white
        lda #$02
        bne fuel_alarm_set_gauge_colour
fuel_alarm_gauge_white
        lda #$01
fuel_alarm_set_gauge_colour
        sta gauge_colour
fuel_alarm_done
        rts
